// @nodegx:generated by `nodegx export --target html` — Story/Sidebar.
import { batch, value } from '../lib/core.js';
import { el, life, truthy, when } from '../lib/dom.js';

/**
 * What you carry
 *
 * Draws into `element` (before `before`, when given). `inputs` are what the parent sets:
 * `things`, `hasThings`.
 * Returns `update(inputs)` to change them, `outputs`, and `destroy()` to take it off the page.
 */
export function mountSidebar(element, inputs = {}, before) {
  const l = life();
  const given = Object.assign({}, inputs);
  const input = { things: value(inputs['things']), hasThings: value(inputs['hasThings']) };

  const sbWrap = el(element, 'div', 'Sidebar-sbWrap', undefined, before);
  const sbHead = el(sbWrap, 'span', 'Sidebar-sbHead', 'What you carry');
  // The things: on the page while its Mounted is true.
  when(l, sbWrap, function () {
    const on = input.hasThings.get();
    return on === undefined ? true : truthy(on);
  }, function (into, at, l) {
    const sbList = el(into, 'div', 'Sidebar-sbList', undefined, at);
    // One pill per thing: a For Each, drawn from HTX-003 on (see EXPORT-PREFLIGHT.md).
    return sbList;
  });
  const sbEmpty = el(sbWrap, 'p', 'Sidebar-sbEmpty', 'Nothing yet. Some choices hand you something, and some only appear once you are carrying it.');

  return {
    update(next) {
      Object.assign(given, next);
      batch(function () {
        if ('things' in next) input.things.set(next['things']);
        if ('hasThings' in next) input.hasThings.set(next['hasThings']);
      });
    },
    outputs: {},
    destroy() {
      l.destroy();
      sbWrap.remove();
    }
  };
}
